-- PT114-S2-Q2. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT114-S2-Q2$batch03$ AND q.stimulus=$batch03$One way kidney stones can form is when urine produced in the kidneys is overly concentrated with calcium or oxalate. Reducing dietary calcium has been thought, therefore, to decrease the likelihood that calcium will concentrate and form additional stones. Oddly enough, for many people the chances of recurrence are decreased by increasing calcium intake.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent discrepancy described above?$batch03$ AND q.correct_choice=$batch03$D$batch03$) THEN RAISE EXCEPTION 'Question changed: PT114-S2-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT114-S2-Q2$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S2-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT114-S2-Q2$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Kidney stones can form when urine has too much calcium, so cutting dietary calcium was expected to prevent new stones.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$For many people, eating *more* calcium lowers the chance of new stones?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The expectation assumes more calcium in the diet means more calcium in the urine. What if extra calcium leaves the body another way, before reaching the kidneys? Then eating more could put *less* through the kidneys.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a path by which extra dietary calcium reduces the calcium the kidneys handle.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT114-S2-Q2$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Animals on calcium supplements rarely get new stones. That repeats the surprising result without saying why it happens.$batch03$), ($batch03$B$batch03$, $batch03$Adding oxalate while cutting calcium is a different change from adding calcium. It does not explain why more calcium helps.$batch03$), ($batch03$C$batch03$, $batch03$An inherited cause of stones does not explain why extra calcium lowers recurrence.$batch03$), ($batch03$D$batch03$, $batch03$More dietary calcium means more calcium leaves through the intestines and less is left for the kidneys to filter. The urine is less concentrated, so fewer stones form.$batch03$), ($batch03$E$batch03$, $batch03$Stones made of uric acid are not the calcium-oxalate stones the stimulus is about.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT114-S2-Q2$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
